 "content": "def transform(grid):
    # Dividers are full rows/columns of color 2. Each compartment is summarized
    # as 1 when it contains at least two non-background marks, otherwise 9.
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if all(v == 2 for v in grid[r])}
    sep_cols = {c for c in range(w) if all(grid[r][c] == 2 for r in range(h))}
    row_groups, col_groups = [], []
    cur = []
    for r in range(h):
        if r in sep_rows:
            if cur:
                row_groups.append(cur)
                cur = []
        else:
            cur.append(r)
    if cur:
        row_groups.append(cur)
    cur = []
    for c in range(w):
        if c in sep_cols:
            if cur:
                col_groups.append(cur)
                cur = []
        else:
            cur.append(c)
    if cur:
        col_groups.append(cur)
    bg = next((v for row in grid for v in row if v not in (2,)), 0)
    out = []
    for rows in row_groups:
        outrow = []
        for cols in col_groups:
            marks = sum(grid[r][c] != bg for r in rows for c in cols)
            outrow.append(1 if marks >= 2 else 9)
        out.append(outrow)
    return out
